From c7ed6ce298ccb8646b33a4599134100ff60e21ac Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:44:15 +0100
Subject: [PATCH] applets/calculator: keep the formula visible while typing
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

The calculator only showed the number being typed, so earlier numbers
and operators disappeared and each operator applied in input order. Show
the formula above the number and calculate it on "=", × and ÷ first.

BUG: 464152
---
 applets/calculator/main.qml | 146 ++++++++++++++++++++++++++----------
 1 file changed, 108 insertions(+), 38 deletions(-)

diff --git a/applets/calculator/main.qml b/applets/calculator/main.qml
index 63bd1dbff..3c2b26f6a 100644
--- a/applets/calculator/main.qml
+++ b/applets/calculator/main.qml
@@ -33,10 +33,10 @@ PlasmoidItem {
     // This is propagated down to all child controls with text

     property real result: 0;
-    property bool hasResult: false;
     property bool showingInput: true;
     property bool showingResult: false;
-    property string operator
+    // Numbers and operators entered so far, ending with "=" once calculated
+    property var terms: []
     property real operand: 0;
     property bool commaPressed: false;
     property int decimals: 0;
@@ -102,31 +102,30 @@ PlasmoidItem {
         displayNumber(operand);
     }

-    function doOperation() {
-        switch (operator) {
-        case "+":
-            result += operand;
-            break;
-        case "-":
-            result -= operand;
-            break;
-        case "*":
-            result *= operand;
-            break;
-        case "/":
-            if (operand === 0) {
-                divisionByZero();
-                return;
+    function evaluate(expression) {
+        // Multiplication and division are done before addition and subtraction
+        const sums = [expression[0]];
+        for (let i = 1; i < expression.length; i += 2) {
+            const value = expression[i + 1];
+            switch (expression[i]) {
+            case "+":
+                sums.push(value);
+                break;
+            case "-":
+                sums.push(-value);
+                break;
+            case "*":
+                sums[sums.length - 1] *= value;
+                break;
+            case "/":
+                if (value === 0) {
+                    return NaN;
+                }
+                sums[sums.length - 1] /= value;
+                break;
             }
-            result /= operand;
-            break;
-        default:
-            return;
         }
-
-        showingInput = false;
-        displayNumber(result);
-        Accessible.announce(i18nc("@info accessible result of calculation", "Result is %1", result))
+        return sums.reduce((sum, value) => sum + value, 0);
     }

     function clearOperand() {
@@ -137,35 +136,84 @@ PlasmoidItem {
     }

     function setOperator(op) {
-        if (!hasResult) {
-            result = operand;
-            hasResult = true;
+        if (showingResult) {
+            terms = [result];
         } else if (showingInput) {
-            doOperation();
+            terms = terms.concat([operand]);
+        } else {
+            // Replace the operator that was just entered
+            terms = terms.slice(0, -1);
         }

+        terms = terms.concat([op]);
         clearOperand();
-        operator = op;
+        showingInput = false;
         showingResult = false;
     }

     function equalsClicked() {
+        let expression;
+        if (showingResult) {
+            // Repeat the last operation on the result
+            if (terms.length < 4) {
+                return;
+            }
+            expression = [result].concat(terms.slice(-3, -1));
+        } else if (showingInput) {
+            expression = terms.concat([operand]);
+        } else {
+            expression = terms.slice(0, -1);
+        }
+
+        terms = expression.concat(["="]);
+        clearOperand();
         showingResult = true;
-        doOperation();
+        result = evaluate(expression);
+        if (isNaN(result)) {
+            divisionByZero();
+            return;
+        }
+
+        showingInput = false;
+        displayNumber(result);
+        Accessible.announce(i18nc("@info accessible result of calculation", "Result is %1", result))
     }

     function clearClicked() {
+        if (showingResult) {
+            allClearClicked();
+            return;
+        }
+
         clearOperand();
-        operator = "";
-        displayNumber(operand);
         showingInput = true;
-        showingResult = false;
+        displayNumber(operand);
     }

     function allClearClicked() {
-        clearClicked();
+        terms = [];
         result = 0;
-        hasResult = false;
+        showingResult = false;
+        clearClicked();
+    }
+
+    function formatFormula(terms) {
+        return terms.map(term => {
+            switch (term) {
+            case "+":
+                return i18nc("Text of the plus button", "+");
+            case "-":
+                return i18nc("Text of the minus button", "-");
+            case "*":
+                return i18nc("Text of the multiplication button", "×");
+            case "/":
+                return i18nc("Text of the division button", "÷");
+            case "=":
+                return i18nc("Text of the equals button", "=");
+            default:
+                return term.toLocaleString(Qt.locale(), "g", 14);
+            }
+        }).join(" ");
     }

     function algarismCount(number) {
@@ -228,6 +276,7 @@ PlasmoidItem {
     function divisionByZero() {
         showingInput = false;
         showingResult = true;
+        result = 0;
         display.text = i18nc("Abbreviation for result (undefined) of division by zero, max. six to nine characters.", "undef");
     }

@@ -323,15 +372,36 @@ PlasmoidItem {
             KSvg.FrameSvgItem {
                 id: displayFrame;
                 Layout.fillWidth: true
-                Layout.minimumHeight: 2 * display.font.pixelSize;
+                Layout.minimumHeight: 2 * display.font.pixelSize + formula.implicitHeight;
                 imagePath: "widgets/frame";
                 prefix: "plain";

+                PlasmaComponents.Label {
+                    id: formula
+                    anchors {
+                        top: parent.top
+                        left: parent.left
+                        right: parent.right
+                        margins: parent.margins.right
+                    }
+                    text: main.formatFormula(main.terms)
+                    textFormat: Text.PlainText
+                    font.pointSize: Kirigami.Theme.defaultFont.pointSize
+                    Kirigami.Theme.colorSet: Kirigami.Theme.View
+                    color: Kirigami.Theme.disabledTextColor
+                    horizontalAlignment: Text.AlignRight
+                    elide: Text.ElideLeft
+                }
+
                 TextEdit {
                     id: display;
                     anchors {
-                        fill: parent;
+                        top: formula.bottom;
+                        left: parent.left;
+                        right: parent.right;
+                        bottom: parent.bottom;
                         margins: parent.margins.right;
+                        topMargin: 0;
                     }
                     text: "0";
                     font.pointSize: Kirigami.Theme.defaultFont.pointSize * 2;
-- 
2.53.0
